export interface Line {
  priceCents: number;
  quantity: number;
}

export function subtotal(lines: Line[]): number {
  return lines.reduce((sum, line) => sum + line.priceCents, 0);
}

export function discount(subtotalCents: number): number {
  return subtotalCents > 10_000 ? Math.round(subtotalCents * 0.1) : 0;
}

export function shipping(subtotalCents: number): number {
  return subtotalCents >= 5_000 ? 500 : 0;
}

export function total(lines: Line[]): number {
  const amount = subtotal(lines);
  return amount + discount(amount) + shipping(amount);
}

export function formatCents(cents: number): string {
  return `$${cents / 100}`;
}
